const bodies = [
{
title:"Preserve required validation checks across repository refreshes",
body:`A resumed run preserves its earlier required validation scripts when refreshing repository metadata. The normal post-worker refresh and the approved inspection-recovery refresh instead replace the repository snapshot wholesale. A check carried by the previous state can disappear from the required set when it is absent from the new manifest. Passing the remaining checks can then make completion eligible even though the earlier requirement is unresolved.

- [Resume retains previous requirements and adds current requirements](https://github.com/petercr/jev-orchestrator/blob/1547e2727d3dacc4b6ce885f47c5cb11fa7c21f9/src/saved-runs/resume.ts#L47-L64)
- [Post-worker state replaces the repository snapshot](https://github.com/petercr/jev-orchestrator/blob/1547e2727d3dacc4b6ce885f47c5cb11fa7c21f9/src/orchestration/loop.ts#L477-L509)
- [Approved inspection recovery also replaces it](https://github.com/petercr/jev-orchestrator/blob/1547e2727d3dacc4b6ce885f47c5cb11fa7c21f9/src/orchestration/loop.ts#L974-L993)

## Acceptance criteria

- [ ] Worker refresh and approved inspection recovery carry forward established required checks while incorporating newly detected requirements.
- [ ] A required check with no current declared script or verified coverage stays pending. If it cannot be run, show why, and keep both recommended and manual completion blocked.
- [ ] Add deterministic regressions for both refresh paths. Cover a resumed requirement, a passing remaining check, and restoration of the missing check followed by fresh independent validation.`
},
{
title:"Bind validation coverage to the manifest used for execution",
body:`Repository inspection computes which checks a declared package workflow covers. A validation candidate carries the package manager and script name, and execution checks the command shape. Passing evidence is later expanded using the coverage in the repository snapshot. A change to the workflow or a script it references between inspection and execution can leave successful evidence credited against stale coverage. Manifest changes during validation can also make it unclear which definition the result applies to.

- [Validation candidate records the script and command](https://github.com/petercr/jev-orchestrator/blob/1547e2727d3dacc4b6ce885f47c5cb11fa7c21f9/src/orchestration/candidate.ts#L330-L359)
- [Executor checks the package-manager command and invokes it](https://github.com/petercr/jev-orchestrator/blob/1547e2727d3dacc4b6ce885f47c5cb11fa7c21f9/src/orchestration/execute.ts#L204-L252)
- [Validation outcomes expand passing records using snapshot coverage](https://github.com/petercr/jev-orchestrator/blob/1547e2727d3dacc4b6ce885f47c5cb11fa7c21f9/src/repo/validation.ts#L73-L84)

## Acceptance criteria

- [ ] Bind approval and passing coverage to the relevant workflow definitions, including referenced package scripts. A definition change detected before execution requires a fresh candidate and approval.
- [ ] If the definitions cannot be verified across execution, keep affected checks pending and completion blocked. Later inspection must not retroactively expand existing passing evidence.
- [ ] Add deterministic regressions for changes before and during a validation attempt, including a referenced script change. Confirm a stable declared workflow still earns credit for its constituent checks.`
}];
store("validation_issues",bodies);
const q=s=>"'"+s.replaceAll("'","'\\''")+"'";
for (const {title,body} of bodies) {
  const cmd=`issue_body=$(mktemp)\ntrap 'rm -f "$issue_body"' EXIT\ncat >"$issue_body" <<'ISSUE_BODY'\n${body}\nISSUE_BODY\ngh issue create --repo petercr/jev-orchestrator --title ${q(title)} --body-file "$issue_body"`;
  const r=await tools.exec_command({cmd,"max_output_tokens":1000});
  text(r);
}

const found=load("validation_issues");
for (const issue of found) {
 const r=await tools.mcp__codex_apps__github_create_issue({repository_full_name:"petercr/jev-orchestrator",...issue});
 text(r);
}

const found=load("validation_issues");
const q=s=>"'"+s.replaceAll("'","'\\''")+"'";
for (const {title,body} of found) {
  const cmd=`issue_body=$(mktemp)\ntrap 'unlink "$issue_body"' EXIT\ncat >"$issue_body" <<'ISSUE_BODY'\n${body}\nISSUE_BODY\ngh issue create --repo petercr/jev-orchestrator --title ${q(title)} --body-file "$issue_body"`;
  const r=await tools.exec_command({cmd,"max_output_tokens":1000});
  text(r);
}

const found=load("validation_issues");
const q=s=>"'"+s.replaceAll("'","'\\''")+"'";
for (const {title,body} of found) {
  const cmd=`gh issue create --repo petercr/jev-orchestrator --title ${q(title)} --body-file - <<'ISSUE_BODY'\n${body}\nISSUE_BODY`;
  const r=await tools.exec_command({cmd,"max_output_tokens":1000});
  text(r);
}

const expected=load("validation_issues");
const actual=await Promise.allSettled([78,79].map(n=>tools.exec_command({cmd:`gh issue view ${n} --repo petercr/jev-orchestrator --json number,title,body,url,state`,"max_output_tokens":2400})));
for (let i=0;i<actual.length;i++) {
  const v=actual[i];
  if(v.status!=="fulfilled"||v.value.exit_code!==0){text(v);continue;}
  const x=JSON.parse(v.value.output);
  const match=x.body.trim()===expected[i].body.trim()&&x.title===expected[i].title;
  text({number:x.number,title:x.title,url:x.url,state:x.state,match});
}
